import{_ as p,a0 as o,w as l,s as m,ao as n,I as r,a1 as t,A as a,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤 | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤 | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid","title":"在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤","tag":"RAID","desc":""},"relativePath":"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid.md","filePath":"[post].md"}'),s={name:"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid.md"};function R(c,d,A,w,D,g){const e=o("Link");return l(),m("div",null,[d[15]||(d[15]=n('<h1 id="在-linux-下使用-raid-七-在-raid-中擴展現有的-raid-陣列和刪除故障的磁盤" tabindex="-1">在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤 <a class="header-anchor" href="#在-linux-下使用-raid-七-在-raid-中擴展現有的-raid-陣列和刪除故障的磁盤" aria-label="Permalink to “在 Linux 下使用 RAID（七）：在 Raid 中擴展現有的 RAID 陣列和刪除故障的磁盤”">​</a></h1><p>每個新手都會對陣列（array）這個詞所代表的意思產生疑惑。陣列只是磁盤的一個集合。換句話説，我們可以稱陣列為一個集合（set）或一組（group）。就像一組雞蛋中包含6個一樣。同樣 RAID 陣列中包含着多個磁盤，可能是2，4，6，8，12，16等，希望你現在知道了什麼是陣列。</p><p>在這裏，我們將看到如何擴展現有的陣列或 RAID 組。例如，如果我們在陣列中使用2個磁盤形成一個 raid 1 集合，在某些情況，如果該組中需要更多的空間，就可以使用 mdadm -grow 命令來擴展陣列大小，只需要將一個磁盤加入到現有的陣列中即可。在説完擴展（添加磁盤到現有的陣列中）後，我們將看看如何從陣列中刪除故障的磁盤。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Growing-Raid-Array.jpg" alt="Grow Raid Array in Linux"></p><p><em>擴展 RAID 陣列和刪除故障的磁盤</em></p><p>假設磁盤中的一個有問題了需要刪除該磁盤，但我們需要在刪除磁盤前添加一個備用磁盤來擴展該鏡像，因為我們需要保存我們的數據。當磁盤發生故障時我們需要從陣列中刪除它，這是這個主題中我們將要學習到的。</p><h4 id="擴展-raid-的特性" tabindex="-1">擴展 RAID 的特性 <a class="header-anchor" href="#擴展-raid-的特性" aria-label="Permalink to “擴展 RAID 的特性”">​</a></h4><ul><li>我們可以增加（擴展）任意 RAID 集合的大小。</li><li>我們可以在使用新磁盤擴展 RAID 陣列後刪除故障的磁盤。</li><li>我們可以擴展 RAID 陣列而無需停機。</li></ul><p>####要求 ####</p><ul><li>為了擴展一個RAID陣列，我們需要一個已有的 RAID 組（陣列）。</li><li>我們需要額外的磁盤來擴展陣列。</li><li>在這裏，我們使用一塊磁盤來擴展現有的陣列。</li></ul><p>在我們瞭解擴展和恢復陣列前，我們必須瞭解有關 RAID 級別和設置的基本知識。點擊下面的鏈接瞭解這些。</p>',11)),r("ul",null,[r("li",null,[t(e,{href:"https://linux.cn/article-6085-1.html"},{default:a(()=>[...d[0]||(d[0]=[i("介紹 RAID 的級別和概念",-1)])]),_:1})]),r("li",null,[t(e,{href:"https://linux.cn/article-6087-1.html"},{default:a(()=>[...d[1]||(d[1]=[i("使用 mdadm 工具創建軟件 RAID 0 （條帶化）",-1)])]),_:1})])]),d[16]||(d[16]=n(`<h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><pre><code>操作系統 	:	CentOS 6.5 Final
 IP地址	 	:	192.168.0.230
 主機名		:	grow.tecmintlocal.com
2 塊現有磁盤 	:	1 GB
1 塊額外磁盤	:	1 GB
</code></pre><p>在這裏，我們已有一個 RAID ，有2塊磁盤，每個大小為1GB，我們現在再增加一個磁盤到我們現有的 RAID 陣列中，其大小為1GB。</p><h3 id="擴展現有的-raid-陣列" tabindex="-1">擴展現有的 RAID 陣列 <a class="header-anchor" href="#擴展現有的-raid-陣列" aria-label="Permalink to “擴展現有的 RAID 陣列”">​</a></h3><p>1、 在擴展陣列前，首先使用下面的命令列出現有的 RAID 陣列。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Existing-Raid-Array.png" alt="Check Existing Raid Array"></p><p><em>檢查現有的 RAID 陣列</em></p><p><strong>注意</strong>: 以上輸出顯示，已經有了兩個磁盤在 RAID 陣列中，級別為 RAID 1。現在我們增加一個磁盤到現有的陣列裏。</p><p>2、 現在讓我們添加新的磁盤“sdd”，並使用<code>fdisk</code>命令來創建分區。</p><pre><code># fdisk /dev/sdd
</code></pre><p>請使用以下步驟為 /dev/sdd 創建一個新的分區。</p><ul><li>按 <code>n</code> 創建新的分區。</li><li>然後按 <code>P</code> 選擇主分區。</li><li>接下來選擇分區號為1。</li><li>只需按兩次回車鍵選擇默認值即可。</li><li>然後，按 <code>P</code> 來打印創建好的分區。</li><li>按 <code>L</code>，列出所有可用的類型。</li><li>按 <code>t</code> 去修改分區。</li><li>鍵入 <code>fd</code> 設置為 Linux 的 RAID 類型，然後按回車確認。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-New-sdd-Partition.png" alt="Create New Partition in Linux"></p><p><em>為 sdd 創建新的分區</em></p><p>3、 一旦新的 sdd 分區創建完成後，你可以使用下面的命令驗證它。</p><pre><code># ls -l /dev/ | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-sdd-Partition.png" alt="Confirm sdd Partition"></p><p><em>確認 sdd 分區</em></p><p>4、 接下來，在添加到陣列前先檢查磁盤是否有 RAID 分區。</p><pre><code># mdadm --examine /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-on-sdd-Partition.png" alt="Check Raid on sdd Partition"></p><p><em>在 sdd 分區中檢查 RAID</em></p><p><strong>注意</strong>:以上輸出顯示，該盤有沒有發現 super-blocks，意味着我們可以將新的磁盤添加到現有陣列。</p><p>5、 要添加新的分區 /dev/sdd1 到現有的陣列 md0，請使用以下命令。</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Add-Disk-To-Raid-Array.png" alt="Add Disk To Raid-Array"></p><p><em>添加磁盤到 RAID 陣列</em></p><p>6、 一旦新的磁盤被添加後，在我們的陣列中檢查新添加的磁盤。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-Disk-Added-To-Raid.png" alt="Confirm Disk Added to Raid"></p><p><em>確認將新磁盤添加到 RAID 中</em></p><p><strong>注意</strong>: 在上面的輸出，你可以看到磁盤已經被添加作為備用的。在這裏，我們的陣列中已經有了2個磁盤，但我們期待陣列中有3個磁盤，因此我們需要擴展陣列。</p><p>7、 要擴展陣列，我們需要使用下面的命令。</p><pre><code># mdadm --grow --raid-devices=3 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Grow-Raid-Array.png" alt="Grow Raid Array"></p><p><em>擴展 Raid 陣列</em></p><p>現在我們可以看到第三塊磁盤(sdd1)已被添加到陣列中，在第三塊磁盤被添加後，它將從另外兩塊磁盤上同步數據。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-Raid-Array.png" alt="Confirm Raid Array"></p><p><em>確認 Raid 陣列</em></p><p><strong>注意</strong>: 對於大容量磁盤會需要幾個小時來同步數據。在這裏，我們使用的是1GB的虛擬磁盤，所以它非常快在幾秒鐘內便會完成。</p><h3 id="從陣列中刪除磁盤" tabindex="-1">從陣列中刪除磁盤 <a class="header-anchor" href="#從陣列中刪除磁盤" aria-label="Permalink to “從陣列中刪除磁盤”">​</a></h3><p>8、 在數據被從其他兩個磁盤同步到新磁盤<code>sdd1</code>後，現在三個磁盤中的數據已經相同了（鏡像）。</p><p>正如我前面所説的，假定一個磁盤出問題了需要被刪除。所以，現在假設磁盤<code>sdc1</code>出問題了，需要從現有陣列中刪除。</p><p>在刪除磁盤前我們要將其標記為失效，然後我們才可以將其刪除。</p><pre><code># mdadm --fail /dev/md0 /dev/sdc1
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Disk-Fail-in-Raid-Array.png" alt="Disk Fail in Raid Array"></p><p><em>在 RAID 陣列中模擬磁盤故障</em></p><p>從上面的輸出中，我們清楚地看到，磁盤在下面被標記為 faulty。即使它是 faulty 的，我們仍然可以看到 raid 設備有3個，1個損壞了，狀態是 degraded。</p><p>現在我們要從陣列中刪除 faulty 的磁盤，raid 設備將像之前一樣繼續有2個設備。</p><pre><code># mdadm --remove /dev/md0 /dev/sdc1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Remove-Disk-in-Raid-Array.png" alt="Remove Disk in Raid Array"></p><p><em>在 Raid 陣列中刪除磁盤</em></p><p>9、 一旦故障的磁盤被刪除，然後我們只能使用2個磁盤來擴展 raid 陣列了。</p><pre><code># mdadm --grow --raid-devices=2 /dev/md0
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Grow-Disks-in-Raid-Array.png" alt="Grow Disks in Raid Array"></p><p><em>在 RAID 陣列擴展磁盤</em></p><p>從上面的輸出中可以看到，我們的陣列中僅有2台設備。如果你需要再次擴展陣列，按照如上所述的同樣步驟進行。如果你需要添加一個磁盤作為備用，將其標記為 spare，因此，如果磁盤出現故障時，它會自動頂上去並重建數據。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這篇文章中，我們已經看到了如何擴展現有的 RAID 集合，以及如何在重新同步已有磁盤的數據後從一個陣列中刪除故障磁盤。所有這些步驟都可以不用停機來完成。在數據同步期間，系統用户，文件和應用程序不會受到任何影響。</p><p>在接下來的文章我將告訴你如何管理 RAID，敬請關注更新，不要忘了寫評論。</p><hr>`,63)),r("p",null,[d[3]||(d[3]=i("via: ",-1)),t(e,{href:"http://www.tecmint.com/grow-raid-array-in-linux/"},{default:a(()=>[...d[2]||(d[2]=[i("http://www.tecmint.com/grow-raid-array-in-linux/",-1)])]),_:1})]),r("p",null,[d[7]||(d[7]=i("作者：",-1)),t(e,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...d[4]||(d[4]=[i("Babin Lonston",-1)])]),_:1}),d[8]||(d[8]=i(" 譯者：",-1)),t(e,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...d[5]||(d[5]=[i("strugglingyouth",-1)])]),_:1}),d[9]||(d[9]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...d[6]||(d[6]=[i("wxy",-1)])]),_:1})]),r("p",null,[d[12]||(d[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...d[10]||(d[10]=[i("LCTT",-1)])]),_:1}),d[13]||(d[13]=i(" 原創翻譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...d[11]||(d[11]=[i("Linux中國",-1)])]),_:1}),d[14]||(d[14]=i(" 榮譽推出",-1))])])}const h=p(s,[["render",R]]);export{f as __pageData,h as default};
